const $=id=>document.getElementById(id);
const token=new URLSearchParams(location.hash.slice(1)).get('token')||sessionStorage.getItem('bkkSimToken')||'';
if(token)sessionStorage.setItem('bkkSimToken',token);
let state={},timer,vehicleMarkers=[],selectedMarker,phoneMarker,pathLayer,trailLayer,loadedPath='',pending=false,arrowPending=false;
const map=L.map('map',{keyboard:false}).setView([47.5,19.05],13);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);
function note(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';$('message').style.display='block';clearTimeout(note.timeout);note.timeout=setTimeout(()=>$('message').style.display='none',9000);}
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result;}
async function action(body){state=await api('action',body);render();return state;}
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const busIcon=(line,selected=false)=>L.divIcon({className:'',html:`<div class="bus-marker ${selected?'selected':''}">${esc(line)}</div>`,iconSize:[34,28],iconAnchor:[17,14]});
function mode(){const live=state.mode==='ha';$('haTab').classList.toggle('active',live);$('replayTab').classList.toggle('active',!live);$('modeHint').textContent=live?`Writes only ${state.entity}. Real BKK positions and your installed HA integration; real elapsed time is required.`:'Virtual vehicle on a real BKK route. Uses the production detector locally. No HA writes.';$('resultOrigin').textContent=live?'RESULT FROM INSTALLED HA INTEGRATION':'LOCAL PRODUCTION DETECTOR · VIRTUAL CLOCK';$('clockField').hidden=live;$('removeMock').hidden=!live;}
function render(){
 mode();
 if(state.phone){
  if(!phoneMarker){phoneMarker=L.marker(state.phone,{draggable:true,icon:L.divIcon({className:'',html:'<div class="phone-marker"></div>',iconSize:[28,28],iconAnchor:[14,14]})}).addTo(map);phoneMarker.bindTooltip('Mock phone');phoneMarker.on('dragend',()=>manualMove([phoneMarker.getLatLng().lat,phoneMarker.getLatLng().lng]));}
  phoneMarker.setLatLng(state.phone);$('phoneLocation').textContent=state.phone.map(v=>v.toFixed(5)).join(', ');
 }
 if(state.vehicle){if(!selectedMarker)selectedMarker=L.marker([state.vehicle.lat,state.vehicle.lon],{icon:busIcon(state.vehicle.line,true)}).addTo(map);else selectedMarker.setLatLng([state.vehicle.lat,state.vehicle.lon]).setIcon(busIcon(state.vehicle.line,true));}
 if(state.path?.length&&loadedPath!==JSON.stringify(state.path)){if(pathLayer)map.removeLayer(pathLayer);pathLayer=L.polyline(state.path,{color:'#2e8b67',weight:5,opacity:.6}).addTo(map);loadedPath=JSON.stringify(state.path);}
 if(trailLayer)map.removeLayer(trailLayer);if(state.reports?.length)trailLayer=L.polyline(state.reports.map(p=>p.position),{color:'#287fca',weight:3,opacity:.8,dashArray:'5,5'}).addTo(map);
 const live=state.mode==='ha';const actual=live?state.haEntities?.find(e=>e.entity_id.startsWith('sensor.')&&e.attributes?.status):null;
 const result=live?(actual?.attributes||null):state.result;
 const status=result?.status|| (live?'waiting_for_ha':'not_on_transit');
 const labels={on_transit:'On vehicle',not_on_transit:'Not on a vehicle',uncertain:'Uncertain',ambiguous:'Multiple candidates',no_gps:'No GPS',stale:'Stale GPS',waiting_for_ha:'Waiting for HA'};
 $('status').textContent=state.vehicle?(labels[status]||status):'Choose a vehicle';
 document.querySelector('.status-box').className='status-box'+(status==='on_transit'?' on':['uncertain','ambiguous','stale'].includes(status)?' uncertain':'');
 $('confidence').textContent=result?`${Math.round((result.confidence||0)*100)}% confidence`:'—';
 const candidate=result?.candidates?.[0];$('detectionDetail').textContent=result?.error||(candidate?`${candidate.reason.replaceAll('_',' ')} · ${candidate.matched_segments??0}/${candidate.required_segments??3} moving segments · ${candidate.travel_meters??0}/${candidate.required_travel_meters??100} m · ${candidate.independent_vehicle_reports??0}/${candidate.required_vehicle_reports??4} vehicle reports`:(result?.detection_reason||'').replaceAll('_',' '));
 const match=result?.match||{};
 $('matchInfo').textContent=live?(actual?`${actual.entity_id} · ${actual.state}`:state.haError||'No mock detector entity yet. Check that BKK Detect is installed, enabled, and includes this mock tracker.'):(state.vehicle?`${match.line||state.vehicle.line} · ${match.vehicle_id||state.vehicle.id} · ${state.reports.length} GPS reports`:'Choose a vehicle with a route shape.');
 $('reports').textContent=state.reports?.length||0;$('budget').textContent=`${state.budgetUsed||0} / ${state.budgetLimit||6} per minute`;
 $('separation').textContent=state.phone&&state.vehicle?`${Math.round(map.distance(state.phone,[state.vehicle.lat,state.vehicle.lon]))} m`:'—';
 $('raw').textContent=JSON.stringify(live?(state.haEntities||[]):state.result||{},null,2);
 const events=live?deriveLiveEvents(result):state.events||[];
 $('events').replaceChildren();if(!events.length)$('events').textContent='Boarding and alighting will appear here, including backfilled timestamps.';
 for(const e of events.slice(-6).reverse()){const row=document.createElement('div');row.className='event';const title=document.createElement('b');title.textContent=e.type;const detail=document.createElement('span');const timing=e.journey?.[e.type];detail.textContent=timing?`${new Date(timing.estimated_at).toLocaleTimeString()} · confirmed ${timing.backfilled_seconds}s later${timing.stop?' · near '+timing.stop.name:''}`:JSON.stringify(e);row.append(title,detail);$('events').append(row);}
}
function deriveLiveEvents(result){if(!result)return[];const journey=result.active_journey||result.last_journey;const list=[];if(journey?.boarding)list.push({type:'boarding',journey});if(journey?.alighting)list.push({type:'alighting',journey});return list;}
async function find(nearby=false){$('find').disabled=true;try{const center=map.getCenter();const data=await api(`vehicles?lat=${center.lat}&lon=${center.lng}&line=${nearby?'':encodeURIComponent($('line').value.trim())}`);for(const marker of vehicleMarkers)map.removeLayer(marker);vehicleMarkers=[];$('vehicle').replaceChildren(new Option(data.vehicles.length?'Select a vehicle':'No vehicles found',''));$('vehicleList').replaceChildren();for(const vehicle of data.vehicles){const row=document.createElement('div');row.className='vehicle-row';const rowLabel=document.createElement('span');rowLabel.textContent=`${vehicle.line} · ${vehicle.headsign} · ${vehicle.id}`;const button=document.createElement('button');button.textContent='Follow';button.onclick=()=>choose(vehicle.id);row.append(rowLabel,button);$('vehicleList').append(row);$('vehicle').append(new Option(`${vehicle.line} · ${vehicle.mode} · ${vehicle.headsign} · ${vehicle.id}`,vehicle.id));const m=L.marker([vehicle.lat,vehicle.lon],{icon:busIcon(vehicle.line)}).addTo(map);const label=document.createElement('span');label.textContent=`${vehicle.line} · ${vehicle.headsign}`;m.bindTooltip(label);m.on('click',()=>choose(vehicle.id));vehicleMarkers.push(m);}if(data.vehicles.length){map.fitBounds(L.latLngBounds(data.vehicles.map(v=>[v.lat,v.lon])).pad(.15));}else note('No vehicles found. Try another line or move the map.');}catch(e){note(e.message,true);}finally{$('find').disabled=false;}}
async function choose(id){stop();try{await action({action:'mode',mode:'ha'});await action({action:'select',id});$('follow').checked=true;await step();$('play').textContent='Ⅱ Stop following';timer=setInterval(step,15000);$('vehicle').value=id;if(state.vehicle)map.setView([state.vehicle.lat,state.vehicle.lon],16);note('Following this real vehicle 1:1. The mock tracker is sent to HA every 15 seconds.');}catch(e){note(e.message,true);}}
async function step(){if(pending)return;pending=true;try{await action({action:'step',seconds:Number($('seconds').value),speed:Number($('speed').value),follow:$('follow').checked});if(state.mode==='ha'){state=await api('status');render();}}catch(e){note(e.message,true);stop();}finally{pending=false;}}
function stop(){clearInterval(timer);timer=null;$('play').textContent='▶ Follow';}
async function manualMove(position,heading){$('follow').checked=false;try{await action(position?{action:'move',position}:{action:'move',heading,metres:Number($('moveMetres').value)});}catch(e){note(e.message,true);}}
$('find').onclick=()=>find();$('nearby').onclick=()=>find(true);$('vehicle').onchange=()=>choose($('vehicle').value);$('line').onkeydown=e=>{if(e.key==='Enter')find();};
$('play').onclick=()=>{if(timer){stop();return;}if(!state.vehicle){note('Find and select a vehicle first.',true);return;}$('play').textContent='Ⅱ Stop following';step();timer=setInterval(step,state.mode==='ha'?15000:1000);};$('step').onclick=step;
$('reset').onclick=async()=>{stop();try{await action({action:'reset'});}catch(e){note(e.message,true);}};
$('off').onclick=async()=>{$('follow').checked=false;try{await action({action:'getoff'});note('Mock phone moved away. Keep Play running, or press Step twice, to confirm alighting.');}catch(e){note(e.message,true);}};
$('stay').onclick=()=>{$('follow').checked=false;note('Phone holds its position while the vehicle continues.');};
for(const [id,newMode] of [['replayTab','replay'],['haTab','ha']])$(id).onclick=async()=>{stop();try{await action({action:'mode',mode:newMode});if(newMode==='ha')note('Live mode writes a separate mock tracker to HA. It uses real time, not accelerated replay.');}catch(e){note(e.message,true);}};
for(const b of document.querySelectorAll('[data-heading]'))b.onclick=()=>manualMove(null,Number(b.dataset.heading));
document.addEventListener('keydown',async e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||$('connections').open)return;const heading={ArrowUp:0,ArrowRight:90,ArrowDown:180,ArrowLeft:270}[e.key];if(heading===undefined)return;e.preventDefault();if(arrowPending)return;arrowPending=true;await manualMove(null,heading);setTimeout(()=>arrowPending=false,130);});
map.on('click',e=>manualMove([e.latlng.lat,e.latlng.lng]));
$('settingsButton').onclick=()=>{$('connections').showModal();};$('closeSettings').onclick=()=>$('connections').close();
$('settingsForm').onsubmit=async e=>{e.preventDefault();try{await api('config',{haUrl:$('haUrl').value,haToken:$('haToken').value,bkkKey:$('bkkKey').value,provider:$('provider').value,mavBaseUrl:$('mavBaseUrl').value,mavRouter:$('mavRouter').value});$('haToken').value='';$('bkkKey').value='';$('connections').close();note('Connection settings updated for this server session.');await initializeMap();}catch(error){note(error.message,true);}};
$('removeMock').onclick=async()=>{stop();try{await action({action:'delete'});note('Mock tracker removed from HA. The recorded detection journal remains available.');}catch(e){note(e.message,true);}};
$('applyOptions').onclick=async()=>{stop();const values={};for(const el of document.querySelectorAll('[data-option]'))values[el.dataset.option]=Number(el.value);try{await action({action:'options',values});note('Local detector reset with these thresholds. Installed HA settings were not changed.');}catch(e){note(e.message,true);}};
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bkkdetect-simulator-session.json';a.click();URL.revokeObjectURL(url);};
async function initializeMap(){try{const data=await api('bootstrap');map.setView(data.center,14);}catch(e){note(e.message,true);}}
try{const config=await api('config');$('haUrl').value=config.haUrl;$('provider').value=config.provider;$('mavBaseUrl').value=config.mavBaseUrl;$('mavRouter').value=config.mavRouter;$('haToken').placeholder=config.hasHaToken?'Saved server-side · leave blank to keep':'Enter token';$('bkkKey').placeholder=config.hasBkkKey?'Saved server-side · leave blank to keep':'Enter BKK key';for(const [key,value]of Object.entries(config.options)){const label=document.createElement('label');label.textContent=key.replaceAll('_',' ');const input=document.createElement('input');input.type='number';input.step='any';input.value=value;input.dataset.option=key;label.append(input);$('thresholds').append(label);}await initializeMap();state=await api('status');if(state.mode!=='ha')await action({action:'mode',mode:'ha'});render();await find(true);}catch(e){note(e.message,true);}
setInterval(async()=>{if(pending)return;try{state=await api('status');render();}catch{}},2000);
